class HomeScreen extends StatefulWidget{const HomeScreen({super.key,required this.service});final GoogleSheetsService service;@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{LoadState<List<AdModel>> state=LoadState.loading();@override void initState(){super.initState();_load();}Future<void> _load()async{final r=await widget.service.fetchAds();if(mounted)setState(()=>state=r);}Future<void> _call(AdModel ad)async{await AnalyticsService.instance.adClicked(ad.advertiserName);final p=ad.phone.replaceAll(RegExp(r'[^0-9+]'),'');if(p.isNotEmpty)await launchUrl(Uri(scheme:'tel',path:p));}@override Widget build(BuildContext context)=>CupertinoPageScaffold(navigationBar:const CupertinoNavigationBar(largeTitle:Text('جيرود')),child:SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[const Text('خدمات البلدة في مكان واحد',style:TextStyle(fontSize:24,fontWeight:FontWeight.w800)),const SizedBox(height:6),Text('مياه، صيدليات، طوارئ، إعلانات ومفقودات وموجودات.',style:TextStyle(color:CupertinoColors.secondaryLabel.resolveFrom(context))),const SizedBox(height:20),SizedBox(height:300,child:StateView(state:state,onRetry:_load,builder:(ads,cached){final ad=ads.first;return Column(children:[CachedBanner(visible:cached),Expanded(child:GlassCard(padding:EdgeInsets.zero,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Expanded(child:ad.imageUrl.isEmpty?const Center(child:Icon(CupertinoIcons.photo,size:48)):ClipRRect(borderRadius:const BorderRadius.vertical(top:Radius.circular(20)),child:CachedNetworkImage(imageUrl:ad.imageUrl,fit:BoxFit.cover,placeholder:(_,__)=>const Center(child:CupertinoActivityIndicator()),errorWidget:(_,__,___)=>const Center(child:Icon(CupertinoIcons.photo,size:48))))),Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:Text(ad.advertiserName.isEmpty?'إعلان':ad.advertiserName,style:const TextStyle(fontWeight:FontWeight.w700))),if(ad.phone.isNotEmpty)CupertinoButton.padding(padding:const EdgeInsets.symmetric(horizontal:12,vertical:6),onPressed:()=>_call(ad),child:const Text('اتصال'))]))])))]);})),const SizedBox(height:18),const GlassCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('مرحباً بك في تطبيق جيرود',style:TextStyle(fontSize:18,fontWeight:FontWeight.w700)),SizedBox(height:8),Text('استخدم شريط التنقل للوصول السريع إلى الخدمات. تُحفظ آخر نسخة ناجحة من البيانات تلقائياً لتبقى المعلومات متاحة عند ضعف الاتصال.') ])),const AppFooter()]));}
